"""Port of Workers/MiningOptimizationV2/Solver/SolverResult.{h,cpp}: the decision tree generated by the solver.

Probability maps are std::maps in Stardust; here they are dicts, iterated in key order wherever the order matters.
"""

from __future__ import annotations

from collections import deque
from typing import NamedTuple

from stardust.instrumentation import log
from stardust.instrumentation.log_formatting_util import format_probability_map, format_vectorlike
from stardust import config
from stardust.workers.mining_optimization_v2.data_model.position_and_velocity import PositionAndVelocity

EPSILON = 0.000001


class SolverArrivalData(NamedTuple):
    """The arrival frame with the metadata we need for gather takeover (ordered like Stardust's struct)."""
    arrival_frame: int
    ten_distance_frame: int
    resend_always_arrives_frame: int

    def __str__(self) -> str:
        return str(self.arrival_frame)


class SolverResult:
    __slots__ = ("path_to_next_branch", "next_branches", "resend_frames_on_this_branch",
                 "resend_frames_on_all_branches", "arrival_data_with_probabilities", "action_frames_with_probabilities",
                 "delays_with_probabilities")

    def __init__(self) -> None:
        # The positions expected to be visited along the path to the next branch
        # Starts with the position of the node that starts this branch
        self.path_to_next_branch: deque[PositionAndVelocity] = deque()

        # The possible next branches once this branch has been traversed
        # The user can identify which next branch is being followed by checking its first position
        # If this is empty, then this branch is the last part of the path
        self.next_branches: list[SolverResult] = []

        # Frames where we intend to resend while on this branch
        self.resend_frames_on_this_branch: set[int] = set()

        # The total set of frames we might resend from this branch onwards
        self.resend_frames_on_all_branches: set[int] = set()

        # The predicted arrival data to the patch or depot
        self.arrival_data_with_probabilities: dict[SolverArrivalData, float] = {}

        # The predicted "action frame" (transition to mining or delivery of resource)
        # For takeover this does not respect the actual takeover frame - it is simply the frame after arrival where the
        # worker's order process timer reaches zero (weighted by probability if the value is not precisely known)
        self.action_frames_with_probabilities: dict[int, float] = {}

        # The predicted delays (not facing patch, collision); can be negative for returns with preserved speed
        self.delays_with_probabilities: dict[int, float] = {}

    def aggregated_resend_frames_if_stable(self) -> set[int] | None:
        """The resend frames for all branches below this one if they are stable, None otherwise."""
        if not self.next_branches:
            return set(self.resend_frames_on_this_branch)

        first_result = self.next_branches[0].aggregated_resend_frames_if_stable()
        if first_result is None:
            return None

        for next_branch in self.next_branches[1:]:
            next_branch_result = next_branch.aggregated_resend_frames_if_stable()
            if next_branch_result is None:
                return None
            if next_branch_result != first_result:
                return None

        first_result.update(self.resend_frames_on_this_branch)
        return first_result

    def contains_arrival_frame(self, arrival_frame: int) -> bool:
        return any(arrival_data.arrival_frame == arrival_frame for arrival_data in self.arrival_data_with_probabilities)

    def latest_arrival_frame(self) -> int:
        return max((arrival_data.arrival_frame for arrival_data in self.arrival_data_with_probabilities), default=-1)

    def frame_predictions(self) -> str:
        return (f"Arrival frames: {format_probability_map(dict(sorted(self.arrival_data_with_probabilities.items())))}"
                f"\nAction frames: {format_probability_map(dict(sorted(self.action_frames_with_probabilities.items())))}"
                f"\nPost-action delays: {format_probability_map(dict(sorted(self.delays_with_probabilities.items())))}"
                f"\nAll resend frames: {format_vectorlike(sorted(self.resend_frames_on_all_branches))}")

    @staticmethod
    def map_average(probabilities: dict[int, float]) -> float:
        """The average value of the map, weighting each value by its probability. Assumes the probabilities sum up to
        1 (which is the case for the maps not related to patch locking)."""
        if config.LOGGING_ENABLED:
            total = SolverResult.probability_sum(probabilities)
            if total < (1.0 - EPSILON) or total > (1.0 + EPSILON):
                log.get(f"ERROR: Probabilities don't sum to 1; actual value is {total}")

        result = 0.0
        for value, probability in sorted(probabilities.items()):
            result += value * probability
        return result

    @staticmethod
    def probability_sum(probabilities: dict[int, float]) -> float:
        """Sums the probability values of the map. Only relevant for the maps related to patch locking, as the others
        always sum to 1."""
        result = 0.0
        for _, probability in sorted(probabilities.items()):
            result += probability
        return result
